/* Isolated sample map. Never loads battle logic or accesses persistent storage. */
(function(){'use strict';
const T=window.PROTactical,C=window.PROCore,$=id=>document.getElementById(id),D=C.MOVEMENT_DOMAINS,W=12,H=9;
let state=null,selected=null,pending=null,reorg=null,serial=1;
const copy=C.clone,key=(x,y)=>x+','+y,current=()=>state?.groups.find(g=>g.id===selected);
function tile(x,y){const surface=state.surface;if(surface==='space')return {kind:(x+y*3)%7===0?'debris':'space',name:(x+y*3)%7===0?'デブリ':'宇宙',costs:{space:(x+y*3)%7===0?2:1}};if(surface==='water')return {kind:x>6?'deep':'water',name:x>6?'深水':'浅瀬',costs:{water:x>6?2:1,underwater:x>6?2:1,air:1}};if(x===7&&y!==4)return {kind:'water',name:'河川',costs:{water:1,underwater:1,air:1}};if((x===4&&y>1&&y<7)||(x===9&&y<4))return {kind:'mountain',name:'山岳',costs:{ground:3,air:1}};if((x+y*2)%7===0)return {kind:'forest',name:'森林',costs:{ground:2,air:1}};return {kind:'ground',name:x===7?'橋':'平原',costs:{ground:1,air:1}};}
function ranges(g,targetId=null){const out=new Map();if(!g||!T.beforeAction(g))return out;const start=key(g.position.x,g.position.y),budget=T.groupMove(g),queue=[{...g.position,cost:0}];out.set(start,{cost:0,path:[]});while(queue.length){queue.sort((a,b)=>a.cost-b.cost);const n=queue.shift(),entry=out.get(key(n.x,n.y));if(n.cost>entry.cost)continue;if(targetId&&state.groups.some(a=>a.id===targetId&&a.position.x===n.x&&a.position.y===n.y))continue;for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=n.x+dx,y=n.y+dy,k=key(x,y);if(x<0||x>=W||y<0||y>=H||state.groups.some(a=>a.id!==g.id&&a.id!==targetId&&a.position.x===x&&a.position.y===y))continue;const costs=tile(x,y).costs,cost=n.cost+T.stepCost(g,costs);if(cost>budget+1e-9||cost>=(out.get(k)?.cost??Infinity))continue;out.set(k,{cost,path:[...entry.path,costs]});queue.push({x,y,cost});}}return out;}
function tell(s){$('fieldNotice').textContent=s;}
function button(text,fn){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=text;b.onclick=fn;return b;}
function draw(){if(!state)return;const g=current(),r=ranges(reorg?.kind==='split'?reorg.detached:g);$('fieldMission').textContent=state.name+' / 移動操作テスト';$('fieldTurn').textContent='第'+state.turn+'ターン · 自陣営';$('fieldGrid').replaceChildren();for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=tile(x,y),at=state.groups.find(a=>a.position.x===x&&a.position.y===y),reach=r.get(key(x,y)),preview=pending?.x===x&&pending?.y===y,b=button('',()=>pick(x,y));b.className='field-tile '+t.kind+(reach?' reachable':'')+(at?.id===selected?' selected':'')+(preview?' preview':'');b.dataset.x=x;b.dataset.y=y;b.setAttribute('aria-label',`${x+1},${y+1} ${t.name}${at?' '+at.name:''}${reach?' 移動消費'+Number(reach.cost.toFixed(3)):''}`);b.textContent=t.name;if(at){const label=document.createElement('strong');label.textContent=at.name.replace('第','').replace('部隊','');b.append(label);}if(reach){const cost=document.createElement('small');cost.textContent=Number(reach.cost.toFixed(3));b.append(cost);}$('fieldGrid').append(b);}
$('fieldSquads').replaceChildren(...state.groups.map(a=>{const b=button(a.name,()=>select(a.id));b.setAttribute('aria-pressed',String(a.id===selected));return b;}));$('fieldInfo').replaceChildren();$('fieldDomains').replaceChildren();if(g){const title=document.createElement('h3');title.textContent=g.name;const info=document.createElement('p');info.textContent='MOVE '+T.groupMove(g)+' ｜ '+(T.beforeAction(g)?'行動前':T.canAct(g)?'移動済み・攻撃可能':'行動終了');const list=document.createElement('ul');for(const m of g.members){const li=document.createElement('li');li.textContent=m.unit.name+' / '+D[m.domain]+' '+m.unit.movementAptitude[m.domain];list.append(li);}$('fieldInfo').append(title,info,list);for(const d of state.surface==='space'?['space']:state.surface==='water'?['water','underwater','air']:['ground','air']){const b=button(D[d],()=>switchTo(d));b.disabled=!!reorg||!T.canSwitch(g,d);b.setAttribute('aria-pressed',String(g.members.every(m=>m.domain===d)));$('fieldDomains').append(b);}}
$('fieldSplit').disabled=!g||!T.beforeAction(g)||g.members.length<2||!!reorg;$('fieldMerge').disabled=!g||!T.beforeAction(g)||!!reorg;$('fieldTransfer').disabled=!g||!T.beforeAction(g)||!!reorg;$('fieldCommit').disabled=!pending;$('fieldCancel').disabled=!pending&&!reorg;$('fieldWait').disabled=!g||!T.canAct(g)||!!pending||!!reorg;
}
function select(id){selected=id;pending=null;reorg=null;tell('青枠のマスを選んで移動先を指定してください。');draw();}
function pick(x,y){const at=state.groups.find(g=>g.position.x===x&&g.position.y===y),g=current();if(reorg?.kind==='merge'){pending=null;if(!at||at.id===g.id){draw();return;}try{const path=ranges(g,at.id).get(key(x,y));if(!path)throw Error('合流先へ移動できません');validateMerge(g,at);pending={x,y,target:at.id};tell(at.name+'と合流します。確定すると双方が行動終了します。');draw();}catch(e){tell(e.message);draw();}return;}if(at){if(reorg){tell('空きマスを選んでください。');return;}select(at.id);return;}const moving=reorg?.kind==='split'?reorg.detached:g,r=ranges(moving).get(key(x,y));if(!g||!r){tell('このマスへは移動できません。');return;}pending={x,y};tell('移動消費 '+Number(r.cost.toFixed(3))+' / MOVE '+T.groupMove(moving)+'。「移動を確定」で決定します。');draw();}
function validateMerge(a,b){const merged=T.merge(a,b).group;if(!Number.isFinite(T.stepCost(merged,tile(b.position.x,b.position.y).costs)))throw Error('合流後の部隊が現在地に対応していません');return merged;}
function choice(title,build){$('fieldChoiceTitle').textContent=title;$('fieldChoiceBody').replaceChildren();$('fieldChoiceError').textContent='';build($('fieldChoiceBody'));$('fieldChoice').showModal();}
function checks(root,g,prefix){const list=document.createElement('div');list.className='field-checks';for(const m of g.members){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=m.uid;input.name=prefix;label.append(input,document.createTextNode(m.unit.name+' / サイズ'+C.UNIT_SIZES[m.unit.size]));list.append(label);}root.append(list);}
const checked=name=>[...$('fieldChoiceBody').querySelectorAll('input[name="'+name+'"]:checked')].map(n=>n.value);
function startSplit(){const g=current();if(!g||!T.beforeAction(g)||g.members.length<2)return;pending=null;choice('分離するユニットを選択',root=>{checks(root,g,'split');root.append(button('分離先を選ぶ',()=>{try{const parts=T.split(g,checked('split'),'detached-'+serial);parts.detached.position=copy(g.position);parts.detached.name=g.name+'分遣隊';// Source stays occupied; exclude its square only while searching outward.
parts.detached.id=g.id;reorg={kind:'split',...parts};$('fieldChoice').close();tell('分離部隊のMOVE '+T.groupMove(parts.detached)+'。青枠の空きマスを選択してください。');draw();}catch(e){$('fieldChoiceError').textContent=e.message;}}));});}
function startMerge(){const g=current();if(!g||!T.beforeAction(g))return;pending=null;reorg={kind:'merge'};tell('合流先の部隊を選択してください。双方が行動前・合計8体／サイズ8以内である必要があります。');draw();}
function startTransfer(){const g=current();if(!g||!T.beforeAction(g))return;pending=null;const adjacent=state.groups.filter(b=>b.id!==g.id&&b.faction===g.faction&&Math.abs(g.position.x-b.position.x)+Math.abs(g.position.y-b.position.y)===1);choice('隣接部隊との移管・交換',root=>{if(!adjacent.length){root.textContent='隣接する自陣営の部隊がありません。';return;}for(const target of adjacent){const b=button(target.name,()=>transferChoice(g,target));b.disabled=!T.beforeAction(target);root.append(b);}});}
function transferChoice(g,target){$('fieldChoiceTitle').textContent=g.name+' ⇄ '+target.name;$('fieldChoiceError').textContent='';const root=$('fieldChoiceBody');root.replaceChildren();const title=document.createElement('p');title.textContent='両側で渡す個体を選択。確定前は編成を変更しません。';root.append(title);checks(root,g,'toTarget');checks(root,target,'toSource');root.append(button('移管・交換を確定',()=>{try{const result=T.transferAdjacent(g,target,checked('toTarget'),checked('toSource'),{adjacent:(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y)===1});for(const a of [result.source,result.target])if(!Number.isFinite(T.stepCost(a,tile(a.position.x,a.position.y).costs)))throw Error('移管後の部隊が現在地に対応していません');state.groups=state.groups.map(a=>a.id===g.id?result.source:a.id===target.id?result.target:a);$('fieldChoice').close();tell('移管・交換を確定。行動は消費しません。');draw();}catch(e){$('fieldChoiceError').textContent=e.message;}}));}

function switchTo(domain){const g=current();if(!g||reorg||!T.canSwitch(g,domain))return;state.groups=state.groups.map(a=>a.id===g.id?T.switchDomain(g,domain):a);pending=null;tell(D[domain]+'へ切替。行動は消費しません。');draw();}
function deploy(snapshot){const surface={'training-01':'ground','combat-01':'water','combat-02':'space'}[snapshot.missionId];if(!surface)throw Error('Unknown mission');state={surface,name:{'training-01':'機動訓練','combat-01':'沿岸防衛線','combat-02':'軌道上の遭遇'}[snapshot.missionId],turn:1,groups:snapshot.groups.filter(g=>g.members.length).map((g,i)=>({...T.grantReactivation(copy(g)),position:{x:i%3,y:Math.floor(i/3)}}))};if(!state.groups.length)throw Error('出撃部隊がありません');select(state.groups[0].id);}
$('fieldCommit').onclick=()=>{if(!pending)return;const g=current();try{if(reorg?.kind==='merge'){const target=state.groups.find(a=>a.id===pending.target);if(!ranges(g,target.id).has(key(target.position.x,target.position.y)))throw Error('合流先へ移動できません');const merged=validateMerge(g,target);state.groups=state.groups.filter(a=>a.id!==g.id).map(a=>a.id===target.id?merged:a);selected=merged.id;tell('合流しました。双方の個体は行動終了です。');}else{const moving=reorg?.kind==='split'?reorg.detached:g,r=ranges(moving).get(key(pending.x,pending.y));if(!r||!T.canTravel(moving,r.path))return;const moved=T.markMoved(moving);moved.position={x:pending.x,y:pending.y};if(reorg?.kind==='split'){moved.id='detached-'+serial++;state.groups=state.groups.map(a=>a.id===g.id?reorg.source:a);state.groups.push(moved);selected=moved.id;tell('分離先への移動を確定。分離部隊は移動済み・攻撃可能、元部隊は行動前です。');}else{state.groups=state.groups.map(a=>a.id===g.id?moved:a);tell('移動を確定しました。攻撃可能です（攻撃は今後接続）。');}}pending=null;reorg=null;draw();}catch(e){tell(e.message);}};
$('fieldCancel').onclick=()=>{pending=null;reorg=null;tell('操作を取り消しました。');draw();};$('fieldWait').onclick=()=>{const g=current();if(!g||pending||reorg||!T.canAct(g))return;state.groups=state.groups.map(a=>a.id===g.id?T.endAction(g):a);tell(g.name+'は行動終了しました。');draw();};
$('fieldNext').onclick=()=>{if(!state)return;reorg=null;state.groups=T.beginFaction(state.groups,'player');state.turn++;pending=null;tell('敵AIなどの陣営処理は未接続のためスキップ。自陣営ターン開始、全員の行動権を回復しました。');draw();};
$('fieldSplit').onclick=startSplit;$('fieldMerge').onclick=startMerge;$('fieldTransfer').onclick=startTransfer;$('fieldChoiceClose').onclick=()=>$('fieldChoice').close();$('fieldChoice').addEventListener('close',()=>{draw();$('fieldSplit').focus();});
window.PROField={startSplit,startMerge,startTransfer,deploy,show(){if(!state){$('fieldMission').textContent='先に出撃準備で部隊を編成してください。';$('fieldNext').disabled=true;}else{$('fieldNext').disabled=false;draw();}},snapshot:()=>copy(state),reachable:()=>[...ranges(reorg?.kind==='split'?reorg.detached:current())].map(([k,v])=>({key:k,cost:v.cost})),pick,switchTo};
})();
